import numpy as np
# 재활용 예제의 세 가지 길을 할인 반환으로 비교한다
paths = {"왼쪽(S2→S1)": [2], "오른쪽(S2→S3→S4→S5)": [0, 1, 10],
         "왕복 한 번(S2→S3→S4→S3→S4→S5)": [0, 1, 0, 1, 10]}
for g in (1.0, 0.9, 0.5):
    out = []
    for name, r in paths.items():
        R = sum(g**t * rt for t, rt in enumerate(r))
        out.append(f"{name}={R:.3f}")
    print(f"gamma={g}:", ", ".join(out))

import numpy as np
def clip_obj(ratio, adv, eps=0.2):
    return np.minimum(ratio * adv, np.clip(ratio, 1 - eps, 1 + eps) * adv)
for ratio, adv in [(1.5, 2.0), (1.1, 2.0), (0.5, -1.0), (1.5, -1.0), (0.5, 2.0)]:
    print(f"ratio={ratio:.1f} A={adv:+.1f} -> unclipped {ratio*adv:+.2f}, PPO {clip_obj(ratio, adv):+.2f}")
